using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Racer;
public static class CheckRevisionRampBoundary {
 public static string Main(){if(BuildPipeline.isBuildingPlayer)throw new Exception("Wait for build");var race=UnityEngine.Object.FindAnyObjectByType<RaceDirector>();var tree=UnityEngine.Object.FindObjectsByType<WoodlandRoute>().First(b=>b.title=="Tree-Top Trail");var mesh=GameObject.Find("Takeoff - Short treehouse dirt jump").GetComponent<MeshCollider>().sharedMesh;var v=mesh.vertices;var rows=new List<object>();float min=999;foreach(var p in v){float ground=Physics.RaycastAll(p+Vector3.up*150,Vector3.down,300,1).Where(h=>h.collider.name.StartsWith("Ground_")).First().point.y;race.road.Project(p,out float lateral);float gap=lateral-2.65f;if(p.y-ground>.2f)min=Mathf.Min(min,gap);rows.Add(new{station=tree.Project(p,out _),heightAboveGround=p.y-ground,gap});}File.WriteAllText("Docs/ShortcutRevision/ramp-boundary.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{minimumRaisedGap=min,rows}));return "Minimum actual raised ramp edge separation from main trail: "+min;}
}
